-- Phase 48: operational asset and maintenance management. Existing devices,
-- kitchen equipment, suppliers, inventory and checklists remain source of truth.
alter table public.plans add column if not exists asset_management_enabled boolean not null default true;
alter table public.plans add column if not exists preventive_maintenance_enabled boolean not null default true;
alter table public.plans add column if not exists work_orders_enabled boolean not null default true;
alter table public.plans add column if not exists maintenance_analytics_enabled boolean not null default true;
alter table public.plans add column if not exists asset_qr_enabled boolean not null default true;

create table public.asset_categories(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,parent_category_id uuid references public.asset_categories(id) on delete set null,active boolean not null default true,created_at timestamptz not null default now(),unique(organization_id,name));
create table public.assets(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete restrict,name text not null,asset_code text not null,category_id uuid references public.asset_categories(id) on delete set null,asset_type text not null check(asset_type in('kitchen_equipment','refrigeration','electrical','hvac','computer','printer','payment_device','scale','vehicle','furniture','infrastructure','other')),manufacturer text,model text,serial_number text,acquisition_date date,installation_date date,purchase_cost_cents bigint,location_id uuid references public.inventory_locations(id) on delete set null,status text not null default 'operational' check(status in('operational','limited','maintenance','failed','retired','disposed','storage')),criticality text not null default 'medium' check(criticality in('low','medium','high','critical')),warranty_until date,supplier_id uuid references public.suppliers(id) on delete set null,hardware_device_id uuid unique references public.hardware_devices(id) on delete set null,kitchen_equipment_id uuid unique references public.kitchen_equipment(id) on delete set null,replaced_asset_id uuid references public.assets(id) on delete set null,qr_token_hash text unique,active boolean not null default true,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,asset_code));
create table public.asset_documents(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,asset_id uuid not null references public.assets(id) on delete restrict,document_type text not null check(document_type in('invoice','manual','warranty','report','certificate','photo','work_order','other')),storage_path text not null,file_name text not null,sensitive boolean not null default true,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.asset_service_provider_profiles(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,supplier_id uuid not null references public.suppliers(id) on delete cascade,specialty text,coverage text,service_level jsonb not null default '{}',internal_rating numeric check(internal_rating between 0 and 5),active boolean not null default true,created_at timestamptz not null default now(),unique(organization_id,supplier_id));
create table public.maintenance_plans(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,asset_id uuid not null references public.assets(id) on delete restrict,name text not null,maintenance_type text not null check(maintenance_type in('preventive','inspection','calibration','cleaning','lubrication','replacement','custom')),recurrence_type text not null check(recurrence_type in('days','weeks','months','usage_based','manual')),recurrence_value integer check(recurrence_value>0),usage_metric text,next_due_at timestamptz,lead_time_days integer not null default 7 check(lead_time_days>=0),estimated_duration_minutes integer,estimated_cost_cents bigint,assigned_team text,provider_id uuid references public.suppliers(id) on delete set null,checklist_id uuid references public.network_operational_standards(id) on delete set null,active boolean not null default true,last_generated_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.maintenance_work_orders(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete restrict,asset_id uuid not null references public.assets(id) on delete restrict,work_order_number text not null,source text not null check(source in('preventive_plan','failure','inspection','manual','quality_issue','hardware_alert')),source_id uuid,maintenance_plan_id uuid references public.maintenance_plans(id) on delete set null,maintenance_type text not null,title text not null,description text,priority text not null default 'normal' check(priority in('low','normal','high','critical')),status text not null default 'draft' check(status in('draft','scheduled','waiting_parts','waiting_provider','in_progress','paused','completed','cancelled')),assigned_user_id uuid references auth.users(id),provider_id uuid references public.suppliers(id) on delete set null,scheduled_start timestamptz,scheduled_end timestamptz,started_at timestamptz,completed_at timestamptz,estimated_cost_cents bigint,actual_cost_cents bigint,response_due_at timestamptz,resolution_target_at timestamptz,downtime_started_at timestamptz,downtime_ended_at timestamptz,result text,service_performed text,completion_responsible uuid references auth.users(id),critical_signoff_by uuid references auth.users(id),critical_signoff_at timestamptz,version bigint not null default 1,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,work_order_number));
create table public.asset_failures(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete restrict,asset_id uuid not null references public.assets(id) on delete restrict,reported_by uuid references auth.users(id),reported_at timestamptz not null default now(),symptom_category text not null check(symptom_category in('not_powering','noise','leak','temperature','error','other')),symptoms text,severity text not null check(severity in('low','medium','high','critical')),operational_impact text,status text not null default 'reported' check(status in('reported','acknowledged','work_order_created','resolved','closed')),work_order_id uuid references public.maintenance_work_orders(id) on delete set null,hardware_health_event_id bigint references public.hardware_health_events(id) on delete set null,quality_nonconformity_id uuid references public.quality_nonconformities(id) on delete set null,created_at timestamptz not null default now());
create table public.asset_inspections(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete restrict,asset_id uuid not null references public.assets(id) on delete restrict,inspection_type text not null check(inspection_type in('routine','safety','cleaning','calibration','quality','custom')),checklist_id uuid references public.network_operational_standards(id) on delete set null,performed_by uuid references auth.users(id),performed_at timestamptz not null default now(),result text not null check(result in('pass','attention','fail')),notes text,next_action text,work_order_id uuid references public.maintenance_work_orders(id) on delete set null,created_at timestamptz not null default now());
create table public.asset_calibrations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,asset_id uuid not null references public.assets(id) on delete restrict,performed_at timestamptz not null,provider_id uuid references public.suppliers(id) on delete set null,result text not null,certificate_document_id uuid references public.asset_documents(id) on delete set null,valid_until date,created_at timestamptz not null default now());
create table public.maintenance_quotes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,work_order_id uuid not null references public.maintenance_work_orders(id) on delete restrict,provider_id uuid not null references public.suppliers(id) on delete restrict,labor_cost_cents bigint not null default 0,parts_cost_cents bigint not null default 0,total_cost_cents bigint generated always as(labor_cost_cents+parts_cost_cents) stored,estimated_days integer,valid_until date,status text not null default 'requested' check(status in('requested','received','accepted','rejected','expired')),approved_by uuid references auth.users(id),approved_at timestamptz,created_at timestamptz not null default now());
create table public.maintenance_parts_usage(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,work_order_id uuid not null references public.maintenance_work_orders(id) on delete restrict,part_name text not null,inventory_item_id uuid references public.inventory_items(id) on delete set null,quantity numeric not null check(quantity>0),unit_cost_cents bigint not null default 0,total_cost_cents bigint generated always as(round(quantity*unit_cost_cents)) stored,created_at timestamptz not null default now());
create table public.asset_warranties(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,asset_id uuid not null references public.assets(id) on delete restrict,provider_id uuid references public.suppliers(id) on delete set null,provider_name text,start_at date,end_at date,coverage_notes text,document_id uuid references public.asset_documents(id) on delete set null,claim_status text,created_at timestamptz not null default now());
create table public.asset_downtime_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete restrict,asset_id uuid not null references public.assets(id) on delete restrict,started_at timestamptz not null,ended_at timestamptz,reason text not null,work_order_id uuid references public.maintenance_work_orders(id) on delete set null,operational_impact text,capacity_reduction_percent numeric check(capacity_reduction_percent between 0 and 100),estimated_impact_cents bigint,estimate_method text,created_at timestamptz not null default now(),check(ended_at is null or ended_at>=started_at));
create table public.maintenance_costs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete restrict,asset_id uuid not null references public.assets(id) on delete restrict,work_order_id uuid references public.maintenance_work_orders(id) on delete set null,cost_type text not null check(cost_type in('parts','labor','external_service','transport','other')),amount_cents bigint not null check(amount_cents>=0),classification text check(classification in('capex','opex') or classification is null),financial_entry_id uuid references public.financial_entries(id) on delete set null,description text,incurred_at date not null default current_date,created_at timestamptz not null default now());
create table public.asset_transfers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,asset_id uuid not null references public.assets(id) on delete restrict,from_store_id uuid references public.establishments(id) on delete restrict,to_store_id uuid not null references public.establishments(id) on delete restrict,status text not null default 'requested' check(status in('requested','approved','in_transit','received','cancelled')),requested_by uuid references auth.users(id),approved_by uuid references auth.users(id),received_by uuid references auth.users(id),reason text,requested_at timestamptz not null default now(),approved_at timestamptz,received_at timestamptz);
create table public.asset_operational_links(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,asset_id uuid not null references public.assets(id) on delete cascade,link_type text not null check(link_type in('kitchen_station','hardware_station','storage_location','delivery_vehicle','product')),link_id uuid not null,capacity_share_percent numeric check(capacity_share_percent between 0 and 100),auto_capacity_update boolean not null default false,created_at timestamptz not null default now(),unique(asset_id,link_type,link_id));
create table public.asset_alerts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete cascade,asset_id uuid references public.assets(id) on delete cascade,alert_type text not null,severity text not null,dedup_key text not null,status text not null default 'open' check(status in('open','acknowledged','resolved')),evidence jsonb not null default '{}',created_at timestamptz not null default now(),resolved_at timestamptz,unique(organization_id,dedup_key,status));
create table public.asset_offline_events(id uuid primary key,organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,device_id uuid references public.offline_devices(id) on delete set null,event_type text not null check(event_type in('failure_report','inspection','technician_note')),payload jsonb not null,base_version bigint,status text not null default 'pending' check(status in('pending','applied','conflict','rejected')),idempotency_key text not null,error text,created_at timestamptz not null default now(),synced_at timestamptz,unique(store_id,idempotency_key));
create table public.asset_audit_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete set null,actor_user_id uuid references auth.users(id) on delete set null,event_type text not null,entity_type text not null,entity_id uuid,reason text,before_state jsonb,after_state jsonb,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table public.fact_asset_failures(id uuid primary key default gen_random_uuid(),organization_id uuid not null,store_id uuid,asset_id uuid,severity text,status text,reported_at timestamptz,loaded_at timestamptz not null default now());
create table public.fact_maintenance_work_orders(id uuid primary key default gen_random_uuid(),organization_id uuid not null,store_id uuid,asset_id uuid,status text,priority text,completion_minutes integer,actual_cost_cents bigint,loaded_at timestamptz not null default now());
create table public.fact_asset_downtime(id uuid primary key default gen_random_uuid(),organization_id uuid not null,store_id uuid,asset_id uuid,downtime_minutes integer,estimated_impact_cents bigint,loaded_at timestamptz not null default now());
create table public.fact_maintenance_costs(id uuid primary key default gen_random_uuid(),organization_id uuid not null,store_id uuid,asset_id uuid,cost_type text,amount_cents bigint,incurred_at date,loaded_at timestamptz not null default now());
create table public.fact_asset_inspections(id uuid primary key default gen_random_uuid(),organization_id uuid not null,store_id uuid,asset_id uuid,result text,performed_at timestamptz,loaded_at timestamptz not null default now());
create table public.dim_asset(asset_id uuid primary key,organization_id uuid not null,store_id uuid,name text,asset_code text,status text,criticality text,loaded_at timestamptz not null default now());
create table public.dim_asset_category(category_id uuid primary key,organization_id uuid not null,name text,loaded_at timestamptz not null default now());
create table public.dim_maintenance_type(maintenance_type text primary key,label text not null);
create table public.dim_service_provider(provider_id uuid primary key,organization_id uuid not null,name text,loaded_at timestamptz not null default now());

create index assets_org_store_status_idx on public.assets(organization_id,store_id,status);
create index assets_org_code_idx on public.assets(organization_id,asset_code);
create index assets_category_idx on public.assets(category_id);
create index maintenance_plan_due_idx on public.maintenance_plans(organization_id,next_due_at) where active;
create index maintenance_wo_status_idx on public.maintenance_work_orders(organization_id,store_id,status,created_at desc);
create index asset_failure_recent_idx on public.asset_failures(asset_id,reported_at desc);
create index asset_downtime_asset_idx on public.asset_downtime_events(asset_id,started_at desc);
create index asset_audit_entity_idx on public.asset_audit_events(entity_type,entity_id,created_at desc);

do $$ declare t text; begin foreach t in array array['asset_categories','assets','asset_documents','asset_service_provider_profiles','maintenance_plans','maintenance_work_orders','asset_failures','asset_inspections','asset_calibrations','maintenance_quotes','maintenance_parts_usage','asset_warranties','asset_downtime_events','maintenance_costs','asset_transfers','asset_operational_links','asset_alerts','asset_offline_events','asset_audit_events','fact_asset_failures','fact_maintenance_work_orders','fact_asset_downtime','fact_maintenance_costs','fact_asset_inspections','dim_asset','dim_asset_category','dim_maintenance_type','dim_service_provider'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy %I on public.%I for all to service_role using(true) with check(true)',t||'_service_only',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;

insert into public.dim_maintenance_type(maintenance_type,label) values('preventive','Preventiva'),('inspection','Inspeção'),('calibration','Calibração'),('cleaning','Limpeza'),('lubrication','Lubrificação'),('replacement','Substituição'),('custom','Personalizada') on conflict do nothing;
